#[derive(Debug, Clone, Copy, PartialEq)]
enum Role {
    Knight,
    Knave,
    Spy,
}

/// Returns whether `statement` is consistent with the speaker's `role`.
fn consistent(statement: bool, role: Role) -> bool {
    match role {
        Role::Knight => statement,   // must tell the truth
        Role::Knave => !statement,   // must lie
        Role::Spy => true,           // either is allowed
    }
}

fn main() {
    use Role::*;
    let roles = [Knight, Knave, Spy];
    let mut solutions = 0;

    for &alice in &roles {
        for &bob in &roles {
            for &charlie in &roles {
                // Each role assigned to exactly one person.
                if alice == bob || alice == charlie || bob == charlie {
                    continue;
                }

                let alice_says   = charlie == Knave;   // "Charlie is a knave"
                let bob_says     = alice == Knight;    // "Alice is a knight"
                let charlie_says = charlie == Spy;     // "I am the spy"

                if consistent(alice_says, alice)
                    && consistent(bob_says, bob)
                    && consistent(charlie_says, charlie)
                {
                    solutions += 1;
                    println!(
                        "Solution: Alice = {:?}, Bob = {:?}, Charlie = {:?}",
                        alice, bob, charlie
                    );
                }
            }
        }
    }

    println!("Total valid assignments: {}", solutions);
}
```

The program walks every permutation of roles and keeps the ones where each statement is consistent with the speaker's role. Expected output:

```
Solution: Alice = Knight, Bob = Spy, Charlie = Knave
Total valid assignments: 1
